-- PublicEcho Large Seed File 5: Updates, Notifications, Upvotes, and Feedback Ratings
USE publicecho;

-- Clean up previously seeded records for File 5 to prevent duplicate key conflicts during regeneration
DELETE FROM `ComplaintUpvotes` WHERE `upvote_id` >= 100;
DELETE FROM `ComplaintUpdates` WHERE `update_id` >= 100;
DELETE FROM `Notifications` WHERE `notification_id` >= 100;
DELETE FROM `feedback_ratings` WHERE `rating_id` >= 100;

-- Complaint Timeline Updates
ON DUPLICATE KEY UPDATE `complaint_id` = VALUES(`complaint_id`), `update_message` = VALUES(`update_message`), `created_at` = VALUES(`created_at`);

-- Notifications
ON DUPLICATE KEY UPDATE `user_id` = VALUES(`user_id`), `complaint_id` = VALUES(`complaint_id`), `message` = VALUES(`message`), `is_read` = VALUES(`is_read`), `sent_at` = VALUES(`sent_at`);

